s and Chemical Analysis','experimental-techniques-and-chemical-analysis','Separation methods, qualitative analysis and tests for ions and gases','10','2026-08-26T00:00:00.000Z'),('topic_igcse_bio_cell_transport','subj_igcse_biology','Movement into and out of Cells','movement-into-and-out-of-cells','Diffusion, osmosis and active transport across cell membranes','9','2026-08-26T00:00:00.000Z'),('topic_igcse_bio_excretion','subj_igcse_biology','Excretion in Humans','excretion-in-humans','Excretory products, kidneys, nephrons and urine formation','10','2026-08-26T00:00:00.000Z'),('topic_igcse_bio_coordination','subj_igcse_biology','Coordination and Response','coordination-and-response','Nervous control, hormones, tropisms and homeostasis','11','2026-08-26T00:00:00.000Z'),('topic_igcse_addmath_series','subj_igcse_add_math','Series','series','Arithmetic and geometric progressions and binomial expansions','8','2026-08-26T00:00:00.000Z'),('topic_alevel_phys_medical','subj_alevel_physics','Medical Physics','medical-physics','Diagnostic imaging, ultrasound, X-rays and medical applications of physics','7','2026-08-26T00:00:00.000Z'),('topic_alevel_phys_particles','subj_alevel_physics','Particle Physics','particle-physics','Fundamental particles, quarks, leptons and particle interactions','8','2026-08-26T00:00:00.000Z'),('topic_alevel_bio_immunity','subj_alevel_biology','Immunity','immunity','Antigens, immune responses, memory cells and vaccination','8','2026-08-26T00:00:00.000Z'),('topic_alevel_math_diffeq','subj_alevel_math','Differential Equations','differential-equations','Forming and solving first-order differential equations','10','2026-08-26T00:00:00.000Z'),('topic_alevel_fmath_summation','subj_alevel_further_math','Summation of Series','summation-of-series','Finite series, standard sums and the method of differences','7','2026-08-26T00:00:00.000Z'),('topic_alevel_fmath_induction','subj_alevel_further_math','Proof by Induction','proof-by-induction','Inductive proofs for identities, divisibility and matrix results','8','2026-08-26T00:00:00.000Z'),('topic_alevel_fmath_polynomial_roots','subj_alevel_further_math','Roots of Polynomial Equations','roots-of-polynomial-equations','Relations between polynomial roots and coefficients','9','2026-08-26T00:00:00.000Z'),('topic_alevel_fmath_vectors','subj_alevel_further_math','Vectors','vectors','Vector products, lines, planes and distances in three dimensions','10','2026-08-26T00:00:00.000Z'),('topic_alevel_fmath_integration','subj_alevel_further_math','Integration','integration','Advanced integration, arc length and reduction formulae','11','2026-08-26T00:00:00.000Z');CREATE TEMP TABLE _sr (id TEXT,subject_id TEXT,topic_id TEXT,question_text TEXT,question_type TEXT,options TEXT,correct_answer TEXT,explanation TEXT,difficulty TEXT,points INTEGER,marks INTEGER,time_limit INTEGER);INSERT INTO _sr (id,subject_id,topic_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit) SELECT id,subject_id,topic_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit FROM questions WHERE (id GLOB 'q_alevel_bio_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_chem_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_fm_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_math_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_phy_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_addmath_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_bio_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_chem_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_math_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_phy_[0-9][0-9][0-9]');CREATE TEMP TABLE _sf(c INTEGER,n INTEGER,a INTEGER,b INTEGER);INSERT INTO _sf(c,n,a,b) WITH RECURSIVE r(k,v) AS (SELECT row_number() OVER(ORDER BY id),json_array(id,subject_id,topic_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit) FROM (SELECT q.* FROM questions q JOIN _sr s ON s.id=q.id)),w(k,i,n,a,b,v) AS (SELECT k,0,length(v),7,11,v FROM r UNION ALL SELECT k,i+1,n,(a*131+unicode(substr(v,i+1,1)))%2147483647,(b*137+unicode(substr(v,i+1,1)))%2147483629,v FROM w WHERE i<n),f AS (SELECT k,n,a,b FROM w WHERE i=n) SELECT count(*) c,coalesce(sum(n),0) n,coalesce(sum((a*k)%2147483647)%2147483647,0) a,coalesce(sum((b*k)%2147483629)%2147483629,0) b FROM f;CREATE TEMP TABLE _tf(c INTEGER,n INTEGER,a INTEGER,b INTEGER);INSERT INTO _tf(c,n,a,b) WITH RECURSIVE r(k,v) AS (SELECT row_number() OVER(ORDER BY id),json_array(id,subject_id,parent_id,name,slug,description,theory_content,key_formulas,display_order,created_at) FROM topics WHERE id IN('topic_igcse_chem_electrolysis','topic_igcse_chem_analysis','topic_igcse_bio_cell_transport','topic_igcse_bio_excretion','topic_igcse_bio_coordination','topic_igcse_addmath_series','topic_alevel_phys_medical','topic_alevel_phys_particles','topic_alevel_bio_immunity','topic_alevel_math_diffeq','topic_alevel_fmath_summation','topic_alevel_fmath_induction','topic_alevel_fmath_polynomial_roots','topic_alevel_fmath_vectors','topic_alevel_fmath_integration')),w(k,i,n,a,b,v) AS (SELECT k,0,length(v),7,11,v FROM r UNION ALL SELECT k,i+1,n,(a*131+unicode(substr(v,i+1,1)))%2147483647,(b*137+unicode(substr(v,i+1,1)))%2147483629,v FROM w WHERE i<n),f AS (SELECT k,n,a,b FROM w WHERE i=n) SELECT count(*) c,coalesce(sum(n),0) n,coalesce(sum((a*k)%2147483647)%2147483647,0) a,coalesce(sum((b*k)%2147483629)%2147483629,0) b FROM f;CREATE TEMP TABLE _lf(c INTEGER,n INTEGER,a INTEGER,b INTEGER);INSERT INTO _lf(c,n,a,b) WITH RECURSIVE r(k,v) AS (SELECT row_number() OVER(ORDER BY migration_id,entity_type,entity_id,field_name,old_value,new_value),json_array(migration_id,entity_type,entity_id,field_name,old_value,new_value) FROM question_bank_remediation_log WHERE migration_id IN('271_cambridge_topic_remediation_part_1','272_cambridge_topic_remediation_part_2','273_cambridge_topic_remediation_part_3','274_cambridge_topic_remediation_part_4','275_cambridge_topic_remediation_part_5')),w(k,i,n,a,b,v) AS (SELECT k,0,length(v),7,11,v FROM r UNION ALL SELECT k,i+1,n,(a*131+unicode(substr(v,i+1,1)))%2147483647,(b*137+unicode(substr(v,i+1,1)))%2147483629,v FROM w WHERE i<n),f AS (SELECT k,n,a,b FROM w WHERE i=n) SELECT count(*) c,coalesce(sum(n),0) n,coalesce(sum((a*k)%2147483647)%2147483647,0) a,coalesce(sum((b*k)%2147483629)%2147483629,0) b FROM f;INSERT INTO _g271 SELECT CASE WHEN ((((SELECT c=455 AND n=126515 AND a=830621474 AND b=2010748537 FROM _sf) AND (SELECT c=0 AND n=0 AND a=0 AND b=0 FROM _lf)) OR ((SELECT c=455 AND n=128833 AND a=2007753758 AND b=1875584014 FROM _sf) AND (SELECT c=103 AND n=12344 AND a=1336009125 AND b=766578064 FROM _lf))) OR ((SELECT c=455 AND n=137254 AND a=1772630358 AND b=1804962429 FROM _sf) AND (SELECT c=453 AND n=53415 AND a=2055164836 AND b=781945770 FROM _lf))) AND ((SELECT COUNT(*) FROM topics WHERE id IN('topic_igcse_chem_electrolysis','topic_igcse_chem_analysis','topic_igcse_bio_cell_transport','topic_igcse_bio_excretion','topic_igcse_bio_coordination','topic_igcse_addmath_series','topic_alevel_phys_medical','topic_alevel_phys_particles','topic_alevel_bio_immunity','topic_alevel_math_diffeq','topic_alevel_fmath_summation','topic_alevel_fmath_induction','topic_alevel_fmath_polynomial_roots','topic_alevel_fmath_vectors','topic_alevel_fmath_integration'))=0 OR ((SELECT COUNT(*) FROM topics WHERE id IN('topic_igcse_chem_electrolysis','topic_igcse_chem_analysis','topic_igcse_bio_cell_transport','topic_igcse_bio_excretion','topic_igcse_bio_coordination','topic_igcse_addmath_series','topic_alevel_phys_medical','topic_alevel_phys_particles','topic_alevel_bio_immunity','topic_alevel_math_diffeq','topic_alevel_fmath_summation','topic_alevel_fmath_induction','topic_alevel_fmath_polynomial_roots','topic_alevel_fmath_vectors','topic_alevel_fmath_integration'))=15 AND (SELECT c=15 AND n=3101 AND a=958063944 AND b=1971966840 FROM _tf))) AND NOT EXISTS(SELECT 1 FROM _ts s JOIN topics t ON t.subject_id=s.subject_id AND t.id<>s.id AND (t.name=s.name OR t.slug=s.slug)) AND NOT EXISTS(SELECT 1 FROM _ts s LEFT JOIN subjects x ON x.id=s.subject_id WHERE x.id IS NULL OR x.is_active<>1 OR x.exam_type_id<>CASE WHEN s.subject_id LIKE 'subj_igcse_%' THEN 'igcse' ELSE 'cambridge_a2' END) AND (SELECT COUNT(*) FROM _m271)=100 AND NOT EXISTS(SELECT 1 FROM _m271 m LEFT JOIN questions q ON q.id=m.question_id LEFT JOIN topics t ON t.id=m.topic_id LEFT JOIN _ts s ON s.id=m.topic_id WHERE q.id IS NULL OR (t.id IS NULL AND s.id IS NULL) OR q.subject_id<>COALESCE(t.subject_id,s.subject_id)) THEN 1 ELSE 0 END;INSERT OR IGNORE INTO topics(id,subject_id,parent_id,name,slug,description,theory_content,key_formulas,display_order,created_at) SELECT id,subject_id,NULL,name,slug,description,NULL,NULL,display_order,created_at FROM _ts;INSERT OR IGNORE INTO question_bank_remediation_log(migration_id,entity_type,entity_id,field_name,old_value,new_value) VALUES('271_cambridge_topic_remediation_part_1','question','q_alevel_fm_050','correct_answer','1 unit','1/3 unit'),('271_cambridge_topic_remediation_part_1','question','q_alevel_fm_050','explanation','d = |2(1) + 2(2) + 1(3) - 10|/√(4+4+1) = |2 + 4 + 3 - 10|/3 = |-1|/3 = 1/3... Actually: d = |9-10|/3 = 1/3','For 2x + 2y + z - 10 = 0, d = |2(1) + 2(2) + 3 - 10|/√(2² + 2² + 1²) = |9 - 10|/3 = 1/3 unit.'),('271_cambridge_topic_remediation_part_1','question','q_alevel_fm_051','options','["A. 1 + x + x²/2 + x³/6", "B. 1 + x + x² + x³", "C. x + x²/2 + x³/6", "D. 1 + x + x²/2! + x³/3!"]','["A. 1 + x + x²/2 + x³/6","B. 1 + x + x² + x³","C. x + x²/2 + x³/6","D. 1 + x + x²/2 + x³/3"]');UPDATE questions SET correct_answer='1/3 unit',explanation='For 2x + 2y + z - 10 = 0, d = |2(1) + 2(2) + 3 - 10|/√(2² + 2² + 1²) = |9 - 10|/3 = 1/3 unit.' WHERE id='q_alevel_fm_050' AND correct_answer='1 unit' AND explanation='d = |2(1) + 2(2) + 1(3) - 10|/√(4+4+1) = |2 + 4 + 3 - 10|/3 = |-1|/3 = 1/3... Actually: d = |9-10|/3 = 1/3';UPDATE questions SET options='["A. 1 + x + x²/2 + x³/6","B. 1 + x + x² + x³","C. x + x²/2 + x³/6","D. 1 + x + x²/2 + x³/3"]' WHERE id='q_alevel_fm_051' AND options='["A. 1 + x + x²/2 + x³/6", "B. 1 + x + x² + x³", "C. x + x²/2 + x³/6", "D. 1 + x + x²/2! + x³/3!"]';INSERT OR IGNORE INTO question_bank_remediation_log(migration_id,entity_type,entity_id,field_name,old_value,new_value) SELECT '271_cambridge_topic_remediation_part_1','question',q.id,'topic_id',NULL,m.topic_id FROM questions q JOIN _m271 m ON m.question_id=q.id WHERE q.topic_id IS NULL;UPDATE questions SET topic_id=(SELECT topic_id FROM _m271 WHERE question_id=questions.id) WHERE id IN(SELECT question_id FROM _m271) AND topic_id IS NULL;DROP TABLE _lf;DROP TABLE _tf;DROP TABLE _sf;CREATE TEMP TABLE _sf(c INTEGER,n INTEGER,a INTEGER,b INTEGER);INSERT INTO _sf(c,n,a,b) WITH RECURSIVE r(k,v) AS (SELECT row_number() OVER(ORDER BY id),json_array(id,subject_id,topic_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit) FROM (SELECT q.* FROM questions q JOIN _sr s ON s.id=q.id)),w(k,i,n,a,b,v) AS (SELECT k,0,length(v),7,11,v FROM r UNION ALL SELECT k,i+1,n,(a*131+unicode(substr(v,i+1,1)))%2147483647,(b*137+unicode(substr(v,i+1,1)))%2147483629,v FROM w WHERE i<n),f AS (SELECT k,n,a,b FROM w WHERE i=n) SELECT count(*) c,coalesce(sum(n),0) n,coalesce(sum((a*k)%2147483647)%2147483647,0) a,coalesce(sum((b*k)%2147483629)%2147483629,0) b FROM f;CREATE TEMP TABLE _tf(c INTEGER,n INTEGER,a INTEGER,b INTEGER);INSERT INTO _tf(c,n,a,b) WITH RECURSIVE r(k,v) AS (SELECT row_number() OVER(ORDER BY id),json_array(id,subject_id,parent_id,name,slug,description,theory_content,key_formulas,display_order,created_at) FROM topics WHERE id IN('topic_igcse_chem_electrolysis','topic_igcse_chem_analysis','topic_igcse_bio_cell_transport','topic_igcse_bio_excretion','topic_igcse_bio_coordination','topic_igcse_addmath_series','topic_alevel_phys_medical','topic_alevel_phys_particles','topic_alevel_bio_immunity','topic_alevel_math_diffeq','topic_alevel_fmath_summation','topic_alevel_fmath_induction','topic_alev